// 1. Вземаме всички абонати от нода Get Subscribers
const allSubscribersItems = $('Get Subscribers').all();
const allSubscribers = allSubscribersItems.map(item => item.json);

// 2. Вземаме текущия коридор
const currentCorridor = $('Loop Each Corridor').item.json.corridor;
const auditedData = $json;

// Helper функция за намиране на стойност в обект без значение от главни/малки букви в името на колоната
function getColumnValue(obj, possibleNames) {
  const keys = Object.keys(obj);
  for (let name of possibleNames) {
    const foundKey = keys.find(k => k.trim().toLowerCase() === name.toLowerCase());
    if (foundKey && obj[foundKey] !== undefined) {
      return obj[foundKey];
    }
  }
  return '';
}

// 3. Филтрираме абонатите
const matchedSubscribers = allSubscribers.filter(sub => {
  // Търсим колоната за активност (Active?, Active, Status)
  const activeVal = String(getColumnValue(sub, ['Active?', 'Active', 'Status'])).trim().toLowerCase();
  const isActive = activeVal === 'yes' || activeVal === 'true' || activeVal === '1';

  // Търсим колоната за коридорите
  const corridorsRaw = String(getColumnValue(sub, [
    'Corridors (comma separated)', 
    'Corridors', 
    'Corridor', 
    'Corridors '
  ]));

  // Разделяме по запетая и почистваме разстоянията
  const subscriberCorridors = corridorsRaw
    .split(',')
    .map(c => c.trim().toUpperCase());

  const targetCorridor = String(currentCorridor).trim().toUpperCase();

  return isActive && subscriberCorridors.includes(targetCorridor);
});

// 4. Ако НЯМА намерени абонати
if (matchedSubscribers.length === 0) {
  return [{
    json: {
      no_subscribers_found: true,
      corridor: currentCorridor,
      message: "No active subscribers found for this corridor"
    }
  }];
}

// 5. Връщаме намерените абонати
return matchedSubscribers.map(sub => {
  const phone = getColumnValue(sub, ['WhatsApp Number', 'Phone', 'Number', 'Mobile']);
  const name = getColumnValue(sub, ['Exporter Name', 'Name', 'Exporter']);

  return {
    json: {
      no_subscribers_found: false,
      phone_number: phone,
      exporter_name: name,
      corridor: currentCorridor,
      risk_score: auditedData.risk_score || auditedData.json?.risk_score,
      headline: auditedData.headline || auditedData.json?.headline,
      summary: auditedData.summary || auditedData.json?.summary
    }
  };
});
